Q: create me a multi tool in python
A: Here is the python code:

```python
import json
from datetime import datetime
from pathlib import Path


def tool_calculator(expr: str) -> str:
    allowed = set('0123456789+-*/().% ')
    if not expr or any(ch not in allowed for ch in expr):
        raise ValueError('Only basic math expressions are allowed')
    return str(eval(expr, {"__builtins__": {}}, {}))


def tool_case(text: str, mode: str) -> str:
    if mode == 'upper':
        return text.upper()
    if mode == 'lower':
        return text.lower()
    if mode == 'title':
        return text.title()
    return text


def tool_word_count(text: str) -> str:
    words = [w for w in text.split() if w.strip()]
    return f'words={len(words)} chars={len(text)} lines={len(text.splitlines())}'


def tool_batch_rename(folder: str, prefix: str) -> str:
    root = Path(folder)
    if not root.is_dir():
        raise ValueError('Folder not found')
    changed = []
    for idx, path in enumerate(sorted(root.iterdir()), start=1):
        if not path.is_file():
            continue
        target = root / f'{prefix}_{idx:03d}{path.suffix.lower()}'
        if target.exists():
            continue
        path.rename(target)
        changed.append(target.name)
    return f'renamed {len(changed)} files'


TOOLS = {
    '1': ('Calculator', lambda: tool_calculator(input('Expression: ').strip())),
    '2': ('Uppercase text', lambda: tool_case(input('Text: '), 'upper')),
    '3': ('Lowercase text', lambda: tool_case(input('Text: '), 'lower')),
    '4': ('Word count', lambda: tool_word_count(input('Text: '))),
    '5': ('Batch rename files', lambda: tool_batch_rename(input('Folder path: ').strip(), input('Prefix: ').strip() or 'file')),
}


def run_batch(jobs):
    results = []
    for job in jobs:
        tool_id = str(job.get('tool', '')).strip()
        payload = job.get('input', '')
        name, fn = TOOLS[tool_id]
        if tool_id == '1':
            out = tool_calculator(str(payload))
        elif tool_id in {'2', '3'}:
            out = tool_case(str(payload), 'upper' if tool_id == '2' else 'lower')
        elif tool_id == '4':
            out = tool_word_count(str(payload))
        elif tool_id == '5':
            parts = str(payload).split('|', 1)
            folder = parts[0].strip()
            prefix = parts[1].strip() if len(parts) > 1 else 'file'
            out = tool_batch_rename(folder, prefix)
        else:
            out = fn()
        results.append({'tool': name, 'output': out})
    return results


def main():
    print('Navine AI Multi-Tool (batch mode supported)')
    print('1 Calculator  2 Upper  3 Lower  4 Word count  5 Batch rename  b Batch run  q Quit')
    while True:
        choice = input('Select tool: ').strip().lower()
        if choice in {'q', 'quit', 'exit'}:
            break
        if choice == 'b':
            raw = input('Paste JSON jobs [{"tool":"1","input":"1+2"}, ...]: ').strip()
            jobs = json.loads(raw)
            for row in run_batch(jobs):
                print(f"[{row['tool']}] {row['output']}")
            continue
        if choice not in TOOLS:
            print('Unknown tool')
            continue
        name, fn = TOOLS[choice]
        try:
            print(f'[{name}]', fn())
        except Exception as exc:
            print(f'Error: {exc}')


if __name__ == '__main__':
    main()
